window.__game = game;
window.__debug = {
  game,
  start: () => game.startRun(),
  goto: (i) => {
    game.mode = "play";
    if (!game.player) game.startRun();
    game.loadRoom(i);
  },
  blood: (n) => { game.blood = n; },
