      if (c[0] === "katana") game.weapons.add("katana");
    }
  },
  hurtBoss: (n = 40) => { if (game.boss) game.boss.hurt(n, game); },
  killAll: () => { for (const e of game.enemies) e.hurt(9999, game, 1); },
  win: () => { if (game.boss) game.boss.hurt(99999, game); },
};

