507:   updateParticles(dt) {
508:     for (const p of this.particles) {
509:       p.life -= dt;
510:       p.vy += (p.gravity || 0) * dt;
511:       p.x += p.vx * dt;
512:       p.y += p.vy * dt;
513:       if (p.type === "dust") p.vx *= 0.96;
514:     }
515:     this.particles = this.particles.filter((p) => p.life > 0);
516:     if (this.particles.length > 420) this.particles.splice(0, this.particles.length - 420);
517:   }
518: 
519:   updateEffects(dt) {
520:     for (const e of this.effects) e.t += dt;
521:     this.effects = this.effects.filter((e) => e.t < e.dur);
522:   }
523: 
524:   spawnParticle(x, y, vx, vy, life, color, size = 1, gravity = 0, type = "blood") {
525:     this.particles.push({ x, y, vx, vy, life, maxLife: life, color, size, gravity, type });
526:   }
527: 
528:   spawnBlood(x, y, n = 8, color = PAL.blood) {
529:     for (let i = 0; i < n; i++) {
530:       const a = rand(0, Math.PI * 2);
531:       const s = rand(30, 170);
532:       this.spawnParticle(
533:         x + rand(-4, 4), y + rand(-4, 4),
534:         Math.cos(a) * s, Math.sin(a) * s - 50,
535:         rand(0.3, 0.85), Math.random() < 0.25 ? PAL.blood2 : color,
536:         randInt(1, 2), 620, "blood"
537:       );
538:     }
539:   }
540: 
541:   spawnSpark(x, y, n = 5) {
542:     for (let i = 0; i < n; i++) {
543:       const a = rand(0, Math.PI * 2);
544:       const s = rand(30, 130);
545:       this.spawnParticle(x, y, Math.cos(a) * s, Math.sin(a) * s, rand(0.12, 0.35), Math.random() < 0.5 ? PAL.gold : PAL.bone, 1, 180, "spark");
546:     }
547:   }
548: 
549:   spawnDust(x, y, n = 6) {
550:     for (let i = 0; i < n; i++) {
551:       this.spawnParticle(
552:         x + rand(-6, 6), y - rand(0, 4),
553:         rand(-40, 40), rand(-60, -10),
554:         rand(0.25, 0.6), PAL.bone2, randInt(1, 2), -10, "dust"
555:       );
556:     }
557:   }
